/**
 * Simple YAML syntax validator.
 * Validates YAML content for structural correctness without external dependencies.
 */

export interface YamlValidationError {
  line: number;
  column: number;
  message: string;
}

export interface YamlValidationResult {
  valid: boolean;
  errors: YamlValidationError[];
}

function checkIndentation(lines: string[]): YamlValidationError[] {
  const errors: YamlValidationError[] = [];
  let detectedIndentSize = 0;

  for (let i = 0; i < lines.length; i++) {
    const line = lines[i];
    if (line.trim() === "" || line.trimStart().startsWith("#")) {
      continue;
    }

    if (/^\s*\t/.test(line) && /^\s* /.test(line)) {
      errors.push({
        line: i + 1,
        column: 1,
        message: "Mixed tabs and spaces in indentation",
      });
      continue;
    }

    if (line.startsWith("\t")) {
      errors.push({
        line: i + 1,
        column: 1,
        message: "Tab character used for indentation; use spaces instead",
      });
      continue;
    }

    const match = line.match(/^( +)/);
    if (match) {
      const indent = match[1].length;
      if (detectedIndentSize === 0 && indent > 0) {
        detectedIndentSize = indent;
      }
      if (detectedIndentSize > 0 && indent % detectedIndentSize !== 0) {
        errors.push({
          line: i + 1,
          column: 1,
          message: `Inconsistent indentation: expected multiple of ${detectedIndentSize} spaces, found ${indent}`,
        });
      }
    }
  }

  return errors;
}

function checkQuotes(lines: string[]): YamlValidationError[] {
  const errors: YamlValidationError[] = [];

  for (let i = 0; i < lines.length; i++) {
    const line = lines[i];
    if (line.trim() === "" || line.trimStart().startsWith("#")) {
      continue;
    }

    let inSingle = false;
    let inDouble = false;
    let singleStart = -1;
    let doubleStart = -1;

    for (let j = 0; j < line.length; j++) {
      const ch = line[j];
      const prev = j > 0 ? line[j - 1] : "";

      if (ch === "'" && !inDouble && prev !== "\\") {
        if (inSingle) {
          inSingle = false;
        } else {
          inSingle = true;
          singleStart = j;
        }
      } else if (ch === '"' && !inSingle && prev !== "\\") {
        if (inDouble) {
          inDouble = false;
        } else {
          inDouble = true;
          doubleStart = j;
        }
      }
    }

    if (inSingle) {
      errors.push({
        line: i + 1,
        column: singleStart + 1,
        message: "Unclosed single quote",
      });
    }
    if (inDouble) {
      errors.push({
        line: i + 1,
        column: doubleStart + 1,
        message: "Unclosed double quote",
      });
    }
  }

  return errors;
}

function checkColonSpacing(lines: string[]): YamlValidationError[] {
  const errors: YamlValidationError[] = [];

  for (let i = 0; i < lines.length; i++) {
    const line = lines[i];
    const trimmed = line.trim();

    if (trimmed === "" || trimmed.startsWith("#") || trimmed.startsWith("-")) {
      continue;
    }

    // Skip flow-style lines (lines with { or [)
    if (trimmed.startsWith("{") || trimmed.startsWith("[")) {
      continue;
    }

    // Look for mapping pattern: key:value without space
    // Must not be inside quotes
    let inSingle = false;
    let inDouble = false;

    for (let j = 0; j < line.length; j++) {
      const ch = line[j];
      const prev = j > 0 ? line[j - 1] : "";

      if (ch === "'" && !inDouble && prev !== "\\") {
        inSingle = !inSingle;
      } else if (ch === '"' && !inSingle && prev !== "\\") {
        inDouble = !inDouble;
      }

      if (ch === ":" && !inSingle && !inDouble) {
        const next = j + 1 < line.length ? line[j + 1] : "";
        // Valid: colon at end of line, colon followed by space, colon in URL-like context
        if (next !== "" && next !== " " && next !== "\n") {
          // Allow colons in URLs (e.g., http://), timestamps, etc.
          if (next === "/" && j + 2 < line.length && line[j + 2] === "/") {
            break;
          }
          errors.push({
            line: i + 1,
            column: j + 1,
            message: "Missing space after colon in mapping",
          });
        }
        break; // Only check first unquoted colon per line
      }
    }
  }

  return errors;
}

function checkBrackets(content: string, lines: string[]): YamlValidationError[] {
  const errors: YamlValidationError[] = [];
  const stack: { char: string; line: number; column: number }[] = [];

  let inSingle = false;
  let inDouble = false;
  let lineNum = 0;
  let colNum = 0;

  for (let i = 0; i < content.length; i++) {
    const ch = content[i];
    const prev = i > 0 ? content[i - 1] : "";

    if (ch === "\n") {
      lineNum++;
      colNum = 0;
      inSingle = false;
      inDouble = false;
      continue;
    }
    colNum++;

    // Skip comments
    const lineContent = lines[lineNum] ?? "";
    if (lineContent.trimStart().startsWith("#")) {
      continue;
    }

    if (ch === "'" && !inDouble && prev !== "\\") {
      inSingle = !inSingle;
    } else if (ch === '"' && !inSingle && prev !== "\\") {
      inDouble = !inDouble;
    }

    if (inSingle || inDouble) continue;

    if (ch === "[" || ch === "{") {
      stack.push({ char: ch, line: lineNum + 1, column: colNum });
    } else if (ch === "]" || ch === "}") {
      const expected = ch === "]" ? "[" : "{";
      if (stack.length === 0) {
        errors.push({
          line: lineNum + 1,
          column: colNum,
          message: `Unexpected closing '${ch}' without matching opening '${expected}'`,
        });
      } else {
        const top = stack[stack.length - 1];
        if (top.char !== expected) {
          errors.push({
            line: lineNum + 1,
            column: colNum,
            message: `Mismatched bracket: expected closing for '${top.char}' opened at line ${top.line}, found '${ch}'`,
          });
          stack.pop();
        } else {
          stack.pop();
        }
      }
    }
  }

  for (const unclosed of stack) {
    errors.push({
      line: unclosed.line,
      column: unclosed.column,
      message: `Unclosed '${unclosed.char}'`,
    });
  }

  return errors;
}

function checkDuplicateKeys(lines: string[]): YamlValidationError[] {
  const errors: YamlValidationError[] = [];
  const keysByIndent = new Map<number, Set<string>>();
  let prevIndent = -1;

  for (let i = 0; i < lines.length; i++) {
    const line = lines[i];
    const trimmed = line.trim();

    if (trimmed === "" || trimmed.startsWith("#")) {
      continue;
    }

    const indentMatch = line.match(/^( *)/);
    const indent = indentMatch ? indentMatch[1].length : 0;

    // If indent decreased, clear deeper levels
    if (indent < prevIndent) {
      for (const [key] of keysByIndent) {
        if (key > indent) {
          keysByIndent.delete(key);
        }
      }
    }

    // If indent increased, start fresh set for this level
    if (indent > prevIndent) {
      keysByIndent.set(indent, new Set());
    }

    prevIndent = indent;

    // Extract key from mapping line (key: value)
    const keyMatch = trimmed.match(/^([^#:]+?):\s/);
    if (!keyMatch) continue;

    const key = keyMatch[1].trim();
    if (!key || key.startsWith("-")) continue;

    let keysAtLevel = keysByIndent.get(indent);
    if (!keysAtLevel) {
      keysAtLevel = new Set();
      keysByIndent.set(indent, keysAtLevel);
    }

    if (keysAtLevel.has(key)) {
      errors.push({
        line: i + 1,
        column: 1,
        message: `Duplicate key '${key}' at this indentation level`,
      });
    } else {
      keysAtLevel.add(key);
    }
  }

  return errors;
}

/**
 * Validate a YAML string for syntax correctness.
 */
export function validateYaml(content: string): YamlValidationResult {
  if (content.trim() === "") {
    return { valid: true, errors: [] };
  }

  const lines = content.split("\n");
  const errors: YamlValidationError[] = [
    ...checkIndentation(lines),
    ...checkQuotes(lines),
    ...checkColonSpacing(lines),
    ...checkBrackets(content, lines),
    ...checkDuplicateKeys(lines),
  ];

  errors.sort((a, b) => a.line - b.line || a.column - b.column);

  return {
    valid: errors.length === 0,
    errors,
  };
}

