async function main(): Promise<void> {
  const filePath = process.argv[2];
  let content: string;

  if (filePath) {
    const file = Bun.file(filePath);
    const exists = await file.exists();
    if (!exists) {
      console.error(`Error: File not found: ${filePath}`);
      process.exit(2);
    }
    content = await file.text();
  } else {
    console.error("Usage: bun run src/validate-yaml.ts <file-path>");
    process.exit(2);
  }

  const result = validateYaml(content);

  if (result.valid) {
    console.log("Valid YAML");
    process.exit(0);
  } else {
    console.error("Invalid YAML:");
    for (const error of result.errors) {
      console.error(`  Line ${error.line}, Column ${error.column}: ${error.message}`);
    }
    process.exit(1);
  }
}

