    if (ch === "'" && !inDouble && prev !== "\\") {
      inSingle = !inSingle;
    } else if (ch === '"' && !inSingle && prev !== "\\") {
      inDouble = !inDouble;
    }

    if (inSingle || inDouble) continue;

    if (ch === "[" || ch === "{") {
      stack.push({ char: ch, line: lineNum + 1, column: colNum });
    } else if (ch === "]" || ch === "}") {
      const expected = ch === "]" ? "[" : "{";
      if (stack.length === 0) {
        errors.push({
          line: lineNum + 1,
          column: colNum,
          message: `Unexpected closing '${ch}' without matching opening '${expected}'`,
        });
      } else {
        const top = stack[stack.length - 1];
        if (top.char !== expected) {
          errors.push({
            line: lineNum + 1,
            column: colNum,
            message: `Mismatched bracket: expected closing for '${top.char}' opened at line ${top.line}, found '${ch}'`,
          });
          stack.pop();
        } else {
          stack.pop();
        }
      }
    }
  }

  for (const unclosed of stack) {
    errors.push({
      line: unclosed.line,
      column: unclosed.column,
      message: `Unclosed '${unclosed.char}'`,
    });
  }

  return errors;
}

function checkDuplicateKeys(lines: string[]): YamlValidationError[] {
  const errors: YamlValidationError[] = [];
  const keysByIndent = new Map<number, Set<string>>();
  let prevIndent = -1;

  for (let i = 0; i < lines.length; i++) {
    const line = lines[i];
    const trimmed = line.trim();

    if (trimmed === "" || trimmed.startsWith("#")) {
      continue;
    }

    const indentMatch = line.match(/^( *)/);
    const indent = indentMatch ? indentMatch[1].length : 0;

    // If indent decreased, clear deeper levels
    if (indent < prevIndent) {
      for (const [key] of keysByIndent) {
        if (key > indent) {
          keysByIndent.delete(key);
        }
      }
    }

    // If indent increased, start fresh set for this level
    if (indent > prevIndent) {
      keysByIndent.set(indent, new Set());
    }

    prevIndent = indent;

    // Extract key from mapping line (key: value)
    const keyMatch = trimmed.match(/^([^#:]+?):\s/);
    if (!keyMatch) continue;

    const key = keyMatch[1].trim();
    if (!key || key.startsWith("-")) continue;

    let keysAtLevel = keysByIndent.get(indent);
    if (!keysAtLevel) {
      keysAtLevel = new Set();
      keysByIndent.set(indent, keysAtLevel);
    }

    if (keysAtLevel.has(key)) {
      errors.push({
        line: i + 1,
        column: 1,
        message: `Duplicate key '${key}' at this indentation level`,
      });
    } else {
      keysAtLevel.add(key);
    }
  }

  return errors;
}

/**
 * Validate a YAML string for syntax correctness.
 */
export function validateYaml(content: string): YamlValidationResult {
  if (content.trim() === "") {
    return { valid: true, errors: [] };
  }

  const lines = content.split("\n");
  const errors: YamlValidationError[] = [
    ...checkIndentation(lines),
    ...checkQuotes(lines),
    ...checkColonSpacing(lines),
    ...checkBrackets(content, lines),
    ...checkDuplicateKeys(lines),
  ];

  errors.sort((a, b) => a.line - b.line || a.column - b.column);

  return {
    valid: errors.length === 0,
    errors,
  };
}

import { describe, expect, test } from "bun:test";
import { validateYaml } from "./yaml-validator";

describe("yaml-validator", () => {
  describe("valid YAML", () => {
