      const result = validateYaml("name: Alice\nage: 30\n");
      expect(result.valid).toBe(true);
      expect(result.errors).toHaveLength(0);
    });

    test("nested mappings", () => {
      const yaml = `person:
  name: Alice
  address:
    city: Wonderland
    zip: "12345"
`;
      const result = validateYaml(yaml);
      expect(result.valid).toBe(true);
      expect(result.errors).toHaveLength(0);
    });

    test("lists", () => {
      const yaml = `fruits:
  - apple
  - banana
  - cherry
`;
      const result = validateYaml(yaml);
      expect(result.valid).toBe(true);
      expect(result.errors).toHaveLength(0);
    });

    test("empty string", () => {
      const result = validateYaml("");
      expect(result.valid).toBe(true);
      expect(result.errors).toHaveLength(0);
    });

    test("whitespace only", () => {
      const result = validateYaml("   \n  \n");
      expect(result.valid).toBe(true);
      expect(result.errors).toHaveLength(0);
    });

    test("comments only", () => {
      const yaml = `# This is a comment
# Another comment
`;
      const result = validateYaml(yaml);
      expect(result.valid).toBe(true);
      expect(result.errors).toHaveLength(0);
    });

    test("inline flow sequences", () => {
      const yaml = `items: [1, 2, 3]\n`;
      const result = validateYaml(yaml);
      expect(result.valid).toBe(true);
      expect(result.errors).toHaveLength(0);
    });

    test("inline flow mappings", () => {
      const yaml = `person: {name: Alice, age: 30}\n`;
      const result = validateYaml(yaml);
      expect(result.valid).toBe(true);
      expect(result.errors).toHaveLength(0);
    });

    test("quoted values with colons", () => {
      const yaml = `url: "http://example.com"\n`;
      const result = validateYaml(yaml);
      expect(result.valid).toBe(true);
      expect(result.errors).toHaveLength(0);
    });

    test("comments after values", () => {
      const yaml = `name: Alice # a comment\nage: 30\n`;
      const result = validateYaml(yaml);
      expect(result.valid).toBe(true);
      expect(result.errors).toHaveLength(0);
    });
  });

  describe("invalid YAML - indentation", () => {
    test("detects tab indentation", () => {
      const yaml = "name: Alice\n\tage: 30\n";
      const result = validateYaml(yaml);
      expect(result.valid).toBe(false);
      expect(result.errors.length).toBeGreaterThan(0);
      expect(result.errors[0].message).toContain("Tab");
    });

    test("detects mixed tabs and spaces", () => {
      const yaml = "name: Alice\n \tage: 30\n";
      const result = validateYaml(yaml);
      expect(result.valid).toBe(false);
      expect(result.errors[0].message).toContain("Mixed tabs and spaces");
    });

    test("detects inconsistent indentation", () => {
      const yaml = `parent:
  child1: a
   child2: b
`;
      const result = validateYaml(yaml);
      expect(result.valid).toBe(false);
      expect(result.errors.some((e) => e.message.includes("Inconsistent indentation"))).toBe(true);
    });
  });

  describe("invalid YAML - quotes", () => {
    test("detects unclosed double quote", () => {
      const yaml = 'name: "Alice\n';
      const result = validateYaml(yaml);
      expect(result.valid).toBe(false);
      expect(result.errors.some((e) => e.message.includes("Unclosed double quote"))).toBe(true);
    });

    test("detects unclosed single quote", () => {
      const yaml = "name: 'Alice\n";
      const result = validateYaml(yaml);
      expect(result.valid).toBe(false);
      expect(result.errors.some((e) => e.message.includes("Unclosed single quote"))).toBe(true);
    });
  });

  describe("invalid YAML - colon spacing", () => {
    test("detects missing space after colon", () => {
      const yaml = "name:Alice\n";
      const result = validateYaml(yaml);
      expect(result.valid).toBe(false);
      expect(result.errors.some((e) => e.message.includes("Missing space after colon"))).toBe(true);
    });

    test("allows colon at end of line", () => {
      const yaml = "parent:\n  child: value\n";
      const result = validateYaml(yaml);
      expect(result.valid).toBe(true);
    });
  });

  describe("invalid YAML - brackets", () => {
    test("detects unclosed bracket", () => {
      const yaml = "items: [1, 2, 3\n";
      const result = validateYaml(yaml);
      expect(result.valid).toBe(false);
      expect(result.errors.some((e) => e.message.includes("Unclosed"))).toBe(true);
    });

    test("detects unclosed brace", () => {
      const yaml = "person: {name: Alice\n";
      const result = validateYaml(yaml);
      expect(result.valid).toBe(false);
      expect(result.errors.some((e) => e.message.includes("Unclosed"))).toBe(true);
    });

    test("detects unexpected closing bracket", () => {
      const yaml = "items: 1, 2, 3]\n";
      const result = validateYaml(yaml);
      expect(result.valid).toBe(false);
      expect(result.errors.some((e) => e.message.includes("Unexpected closing"))).toBe(true);
    });
  });

  describe("invalid YAML - duplicate keys", () => {
    test("detects duplicate keys at same level", () => {
      const yaml = `name: Alice
age: 30
name: Bob
`;
      const result = validateYaml(yaml);
      expect(result.valid).toBe(false);
      expect(result.errors.some((e) => e.message.includes("Duplicate key"))).toBe(true);
    });

    test("allows same key at different indent levels", () => {
      const yaml = `person:
  name: Alice
address:
  name: Main St
`;
      const result = validateYaml(yaml);
      expect(result.valid).toBe(true);
    });
  });
});

/**
 * CLI entry point for the YAML validator.
 * Usage: bun run src/validate-yaml.ts <file-path>
 */

import { validateYaml } from "./yaml-validator";

async function main(): Promise<void> {
  const filePath = process.argv[2];
  let content: string;

  if (filePath) {
    const file = Bun.file(filePath);
    const exists = await file.exists();
    if (!exists) {
      console.error(`Error: File not found: ${filePath}`);
      process.exit(2);
    }
    content = await file.text();
  } else {
    console.error("Usage: bun run src/validate-yaml.ts <file-path>");
    process.exit(2);
  }

  const result = validateYaml(content);

  if (result.valid) {
    console.log("Valid YAML");
    process.exit(0);
  } else {
    console.error("Invalid YAML:");
    for (const error of result.errors) {
      console.error(`  Line ${error.line}, Column ${error.column}: ${error.message}`);
    }
    process.exit(1);
  }
}

main();

