        "content": "import { describe, expect, test } from \"bun:test\";\nimport { validateYaml } from \"./yaml-validator\";\n\ndescribe(\"validateYaml\", () => {\n  describe(\"valid YAML\", () => {\n    test(\"empty string is valid\", () => {\n      const result = validateYaml(\"\");\n      expect(result.valid).toBe(true);\n    });\n\n    test(\"whitespace-only is valid\", () => {\n      const result = validateYaml(\"   \\n  \\n  \");\n      expect(result.valid).toBe(true);\n    });\n\n    test(\"simple key-value pair\", () => {\n      const result = validateYaml(\"name: Alice\");\n      expect(result.valid).toBe(true);\n    });\n\n    test(\"multiple key-value pairs\", () => {\n      const yaml = \"name: Alice\\nage: 30\\ncity: Wonderland\";\n      const result = validateYaml(yaml);\n      expect(result.valid).toBe(true);\n    });\n\n    test(\"nested mapping\", () => {\n      const yaml = \"person:\\n  name: Alice\\n  age: 30\";\n      const result = validateYaml(yaml);\n      expect(result.valid).toBe(true);\n    });\n\n    test(\"list items\", () => {\n      const yaml = \"fruits:\\n  - apple\\n  - banana\\n  - cherry\";\n      const result = validateYaml(yaml);\n      expect(result.valid).toBe(true);\n    });\n\n    test(\"comments are ignored\", () => {\n      const yaml = \"# This is a comment\\nname: Alice\\n# Another comment\";\n      const result = validateYaml(yaml);\n      expect(result.valid).toBe(true);\n    });\n\n    test(\"document separator\", () => {\n      const yaml = \"---\\nname: Alice\\n...\\n---\\nname: Bob\";\n      const result = validateYaml(yaml);\n      expect(result.valid).toBe(true);\n    });\n\n    test(\"quoted values with colons\", () => {\n      const yaml = 'url: \"http://example.com\"';\n      const result = validateYaml(yaml);\n      expect(result.valid).toBe(true);\n    });\n\n    test(\"empty value after colon\", () => {\n      const yaml = \"name: \\nage: 30\";\n      const result = validateYaml(yaml);\n      expect(result.valid).toBe(true);\n    });\n\n    test(\"key with empty nested block\", () => {\n      const yaml = \"parent:\\n  child: value\";\n      const result = validateYaml(yaml);\n      expect(result.valid).toBe(true);\n    });\n  });\n\n  describe(\"invalid YAML\", () => {\n    test(\"tab indentation\", () => {\n      const yaml = \"name: Alice\\n\\tage: 30\";\n      const result = validateYaml(yaml);\n      expect(result.valid).toBe(false);\n      expect(result.error).toContain(\"Tab\");\n      expect(result.lineNumber).toBe(2);\n    });\n\n    test(\"unclosed single quote\", () => {\n      const yaml = \"name: 'Alice\";\n      const result = validateYaml(yaml);\n      expect(result.valid).toBe(false);\n      expect(result.error).toContain(\"single quote\");\n      expect(result.lineNumber).toBe(1);\n    });\n\n    test(\"unclosed double quote\", () => {\n      const yaml = 'name: \"Alice';\n      const result = validateYaml(yaml);\n      expect(result.valid).toBe(false);\n      expect(result.error).toContain(\"double quote\");\n      expect(result.lineNumber).toBe(1);\n    });\n\n    test(\"missing colon in top-level key\", () => {\n      const yaml = \"name Alice\";\n      const result = validateYaml(yaml);\n      expect(result.valid).toBe(false);\n      expect(result.error).toContain(\"colon\");\n      expect(result.lineNumber).toBe(1);\n    });\n\n    test(\"inconsistent indentation\", () => {\n      const yaml = \"parent:\\n  child1: a\\n   child2: b\";\n      const result = validateYaml(yaml);\n      expect(result.valid).toBe(false);\n      expect(result.error).toContain(\"indentation\");\n      expect(result.lineNumber).toBe(3);\n    });\n\n    test(\"missing space after colon\", () => {\n      const yaml = \"name:Alice\";\n      const result = validateYaml(yaml);\n      expect(result.valid).toBe(false);\n      expect(result.error).toContain(\"space after colon\");\n      expect(result.lineNumber).toBe(1);\n    });\n  });\n\n  describe(\"edge cases\", () => {\n    test(\"single line with just a key and colon\", () => {\n      const yaml = \"name:\";\n      const result = validateYaml(yaml);\n      expect(result.valid).toBe(true);\n    });\n\n    test(\"deeply nested structure\", () => {\n      const yaml = \"a:\\n  b:\\n    c:\\n      d: value\";\n      const result = validateYaml(yaml);\n      expect(result.valid).toBe(true);\n    });\n\n    test(\"mixed lists and mappings\", () => {\n      const yaml = \"items:\\n  - name: apple\\n  - name: banana\";\n      const result = validateYaml(yaml);\n      expect(result.valid).toBe(true);\n    });\n\n    test(\"blank lines between entries\", () => {\n      const yaml = \"name: Alice\\n\\nage: 30\";\n      const result = validateYaml(yaml);\n      expect(result.valid).toBe(true);\n    });\n  });\n});\n"
