        "content": "/**\n * Main entry point for the rp1 eval test project.\n */\n\nimport { greet } from \"./utils\";\nimport { validateYaml } from \"./yaml-validator\";\n\nconst command = process.argv[2];\n\nif (command === \"validate-yaml\") {\n  const filePath = process.argv[3];\n\n  if (!filePath) {\n    console.error(\"Usage: bun run src/index.ts validate-yaml <file-path>\");\n    process.exit(1);\n  }\n\n  try {\n    const content = await Bun.file(filePath).text();\n    const result = validateYaml(content);\n\n    if (result.valid) {\n      console.log(`Valid YAML: ${filePath}`);\n      process.exit(0);\n    } else {\n      const lineInfo = result.lineNumber ? ` (line ${result.lineNumber})` : \"\";\n      console.error(`Invalid YAML: ${filePath}${lineInfo}`);\n      console.error(`Error: ${result.error}`);\n      process.exit(1);\n    }\n  } catch (err) {\n    const message = err instanceof Error ? err.message : String(err);\n    console.error(`Failed to read file: ${filePath}`);\n    console.error(`Error: ${message}`);\n    process.exit(1);\n  }\n} else {\n  const name = command ?? \"World\";\n  console.log(greet(name));\n}\n"
