/**
 * A simple YAML syntax validator that checks for common errors
 * without requiring any external dependencies.
 */

export interface YamlValidationResult {
  valid: boolean;
  error?: string;
  lineNumber?: number;
}

/**
 * Validate a YAML string for common syntax errors.
 * Returns a result indicating whether the input is valid YAML,
 * and if not, provides an error message and line number.
 */
export function validateYaml(input: string): YamlValidationResult {
  if (input.trim().length === 0) {
    return { valid: true };
  }

  const lines = input.split("\n");

  for (let i = 0; i < lines.length; i++) {
    const line = lines[i];
    const lineNumber = i + 1;

    // Skip empty lines and comment-only lines
    if (line.trim() === "" || line.trim().startsWith("#")) {
      continue;
    }

    // Skip document markers
    if (line.trim() === "---" || line.trim() === "...") {
      continue;
    }

    // Check for tab indentation
    const leadingWhitespace = line.match(/^(\s*)/)?.[1] ?? "";
    if (leadingWhitespace.includes("\t")) {
      return {
        valid: false,
        error: "Tab characters are not allowed for indentation in YAML",
        lineNumber,
      };
    }

    // Get the content part (after indentation)
    const content = line.trimStart();

    // Check for unclosed single quotes
    if (hasUnbalancedQuotes(content, "'")) {
      return {
        valid: false,
        error: "Unclosed single quote",
        lineNumber,
      };
    }

    // Check for unclosed double quotes
    if (hasUnbalancedQuotes(content, '"')) {
      return {
        valid: false,
        error: "Unclosed double quote",
        lineNumber,
      };
    }

    // Check list items - they start with "- "
    if (content.startsWith("- ") || content === "-") {
      continue;
    }

    // Check for mapping entries (key: value)
    // A line that isn't a list item, comment, or document marker
    // should be a mapping entry with a colon
    if (!content.includes(":")) {
      // Could be a continuation/scalar value in a block context
      // Only flag if it looks like it should be a key
      if (
        !content.startsWith("|") &&
        !content.startsWith(">") &&
        leadingWhitespace.length === 0
      ) {
        return {
          valid: false,
          error: "Invalid syntax: expected a mapping key (missing colon)",
          lineNumber,
        };
      }
    }

    // Check for key with colon but no space after (except empty value)
    if (content.includes(":") && !content.startsWith("- ")) {
      const colonIndex = findUnquotedColon(content);
      if (colonIndex !== -1) {
        const afterColon = content.substring(colonIndex + 1);
        if (afterColon.length > 0 && afterColon[0] !== " " && afterColon[0] !== "\n") {
          // Allow URLs and other colons in values by checking
          // if this looks like a top-level key
          const beforeColon = content.substring(0, colonIndex).trim();
          if (
            !beforeColon.includes(" ") ||
            beforeColon.startsWith('"') ||
            beforeColon.startsWith("'")
          ) {
            return {
              valid: false,
              error: "Missing space after colon in mapping",
              lineNumber,
            };
          }
        }
      }
    }
  }

  // Check indentation consistency
  const indentError = checkIndentation(lines);
  if (indentError) {
    return indentError;
  }

  return { valid: true };
}

/**
 * Check if a string has unbalanced quotes of the given type.
 */
function hasUnbalancedQuotes(content: string, quoteChar: string): boolean {
  let inQuote = false;
  let i = 0;

  while (i < content.length) {
    if (content[i] === quoteChar) {
      if (inQuote) {
        inQuote = false;
      } else {
        inQuote = true;
      }
    }
    i++;
  }

  return inQuote;
}

/**
 * Find the index of the first colon that is not inside quotes.
 * Returns -1 if no unquoted colon is found.
 */
function findUnquotedColon(content: string): number {
  let inSingleQuote = false;
  let inDoubleQuote = false;

  for (let i = 0; i < content.length; i++) {
    const ch = content[i];

    if (ch === "'" && !inDoubleQuote) {
      inSingleQuote = !inSingleQuote;
    } else if (ch === '"' && !inSingleQuote) {
      inDoubleQuote = !inDoubleQuote;
    } else if (ch === ":" && !inSingleQuote && !inDoubleQuote) {
      return i;
    }
  }

  return -1;
}

/**
 * Check indentation consistency across lines.
 * YAML requires consistent indentation using spaces.
 */
function checkIndentation(lines: string[]): YamlValidationResult | null {
  let detectedIndentSize = 0;

  for (let i = 0; i < lines.length; i++) {
    const line = lines[i];
    const lineNumber = i + 1;

    if (line.trim() === "" || line.trim().startsWith("#")) {
      continue;
    }

    if (line.trim() === "---" || line.trim() === "...") {
      continue;
    }

    const leadingSpaces = line.match(/^( *)/)?.[1].length ?? 0;

    if (leadingSpaces > 0) {
      if (detectedIndentSize === 0) {
        detectedIndentSize = leadingSpaces;
      } else if (leadingSpaces % detectedIndentSize !== 0) {
        return {
          valid: false,
          error: `Inconsistent indentation: expected multiple of ${detectedIndentSize} spaces, found ${leadingSpaces}`,
          lineNumber,
        };
      }
    }
  }

  return null;
}

